-- Wrapper functions for conan_setup, conan_setup_link, and conan_setup_build
-- that add safety checks for missing packages.

-- Store the original functions before redefining them
local original_conan_setup_build = conan_setup_build
local original_conan_setup_link = conan_setup_link
local original_conan_setup = conan_setup

-- Helper function to check if package exists in conandeps
local function package_exists(conf, pkg)
    if conandeps == nil then
        return false
    end
    if conandeps[conf] == nil then
        return false
    end
    if conandeps[conf][pkg] == nil then
        return false
    end
    return true
end

-- Wrapper for conan_setup_build that adds safety checks
function conan_setup_build(conf, pkg)
    if conf == nil and pkg ~= nil then
        -- When conf=nil: set filters for each config
        -- NOTE: This will override any active system/platform filters!
        -- Functions that need to preserve system filters should call original_conan_setup_build directly
        filter { "configurations:debug", "architecture:x86_64" }
            conan_setup_build("debug_x86_64", pkg)
        filter { "configurations:release", "architecture:x86_64" }
            conan_setup_build("release_x86_64", pkg)
        filter {}
    elseif pkg == nil or package_exists(conf, pkg) then
        -- Let the original function handle iteration (pkg == nil) or call it safely (package exists)
        original_conan_setup_build(conf, pkg)
    else
        -- Package doesn't exist - but this might be OK if we're on wrong platform (e.g. Linux package on Windows)
        -- Just silently skip instead of error - Premake filters will prevent this from being used anyway
    end
end

-- Wrapper for conan_setup_link that adds safety checks
function conan_setup_link(conf, pkg)
    if conf == nil and pkg ~= nil then
        -- When conf=nil: set filters for each config
        -- NOTE: This will override any active system/platform filters!
        -- Functions that need to preserve system filters should call original_conan_setup_link directly
        filter { "configurations:debug", "architecture:x86_64" }
            conan_setup_link("debug_x86_64", pkg)
        filter { "configurations:release", "architecture:x86_64" }
            conan_setup_link("release_x86_64", pkg)
        filter {}
    elseif pkg == nil or package_exists(conf, pkg) then
        -- Let the original function handle iteration (pkg == nil) or call it safely (package exists)
        original_conan_setup_link(conf, pkg)
    else
        -- Package doesn't exist - but this might be OK if we're on wrong platform (e.g. Linux package on Windows)
        -- Just silently skip instead of error - Premake filters will prevent this from being used anyway
    end
end

-- Wrapper for conan_setup that adds safety checks  
function conan_setup(conf, pkg)
    if conf == nil and pkg ~= nil then
        -- When conf=nil: set filters for each config
        -- NOTE: This will override any active system/platform filters!
        -- Functions that need to preserve system filters should call original_conan_setup directly
        filter { "configurations:debug", "architecture:x86_64" }
            conan_setup("debug_x86_64", pkg)
        filter { "configurations:release", "architecture:x86_64" }
            conan_setup("release_x86_64", pkg)
        filter {}
    elseif pkg == nil or package_exists(conf, pkg) then
        -- Let the original function handle iteration (pkg == nil) or call it safely (package exists)
        original_conan_setup(conf, pkg)
    else
        -- Package doesn't exist - but this might be OK if we're on wrong platform (e.g. Linux package on Windows)
        -- Just silently skip instead of error - Premake filters will prevent this from being used anyway
    end
end

